#ifndef RESURS_CRYPTO_TYPES_H
#define RESURS_CRYPTO_TYPES_H
/**
 * @file
 * @brief Shared byte sizes used by the AES-256-GCM implementation and wrappers.
 */

#include <cstddef>

namespace resurs::crypto
{
    /// Required raw AES-256 key size; the calling application owns key storage.
    inline constexpr std::size_t AES_256_KEY_SIZE_BYTES = 32;
    /// IV size generated by encryption and required by decryption.
    inline constexpr std::size_t GCM_IV_SIZE_BYTES = 12;
    /// Full authentication tag size required by this module's contract.
    inline constexpr std::size_t GCM_TAG_SIZE_BYTES = 16;

}

#endif
